import { DatabaseCache } from "#core/ui/utilities/utilities-data.js";

export interface SyncretismData {
	description: string;
	age: string;
	civilization: string;
}

export interface SyncretismQueryRow {
	Key?: string;
	KeyName?: string;
	KeyAgeType?: string;
	KeyAgeName?: string;
	CivilizationType?: string;
	CivilizationName?: string;
	AgeType?: string;
	AgeName?: string;
}

function SyncretismQueryTemplate(tableName: string, keyTable: string, keyType: string, keyName: string) {
	return `
		SELECT 
			t.${keyType} as Key,
			k.${keyName} as KeyName,
			ak.AgeType as KeyAgeType,
			ak.Name as KeyAgeName,
			t.UnlockCivilizationType as CivilizationType,
			c.CivilizationName,
			a.AgeType,
			a.Name as AgeName
		FROM ${tableName} t
		INNER JOIN ${keyTable} k
			ON t.${keyType} = k.${keyType}
		INNER JOIN Civilizations c 
			ON t.UnlockCivilizationType = c.CivilizationType
		INNER JOIN Ages a 
			ON c.Domain = a.PlayerCivilizationDomain
		LEFT JOIN Civilizations kc
			ON t.${keyType} = kc.CivilizationType
		LEFT JOIN Ages ak
			ON kc.Domain = ak.PlayerCivilizationDomain
		ORDER BY 
			a.ChronologyIndex ASC;
	`;
}
export const LeaderSyncretismQuery = SyncretismQueryTemplate(
	"LeaderSyncretismUnlocks",
	"Leaders",
	"LeaderType",
	"LeaderName",
);
export const CivSyncretismQuery = SyncretismQueryTemplate(
	"CivilizationSyncretismUnlocks",
	"Civilizations",
	"CivilizationType",
	"CivilizationName",
);

export interface SyncretismUnlockOption {
	Type: string;
	Kind: string;
	Name: string;
	Description: string;
}

interface CivilizationSyncretismUnlocks {
	CivilizationName: string;
	CivilizationType: string;
	AgeType: string;
	AgeName: string;
	Infrastructure: SyncretismUnlockOption[];
	Unit: SyncretismUnlockOption[];
}

interface CivilizationSyncretismInfo {
	Info: Map<string, CivilizationSyncretismUnlocks>;
}

function createSyncretismDataModel(): CivilizationSyncretismInfo {
	const info = new Map<string, CivilizationSyncretismUnlocks>();
	const dbCache = new DatabaseCache("config");

	const civilizationItems = dbCache.query(`
		SELECT 
			ci.*, 
			CASE WHEN se.Type IS NOT NULL THEN se.IncludeAsInfrastructureUpgrade WHEN ci.Kind IS NULL OR ci.Kind <> 'KIND_UNIT' THEN 1 ELSE 0 END AS Infrastructure, 
			CASE WHEN se.Type IS NOT NULL THEN se.IncludeAsUnitUpgrade WHEN ci.Kind = 'KIND_UNIT' THEN 1 ELSE 0 END AS Unit 
		FROM CivilizationItems ci 
		LEFT JOIN SyncretismExceptions se ON ci.Type = se.Type 
		WHERE ci.Kind != "KIND_TRAIT" AND ci.CanSyncretize == 1
		ORDER BY ci.kind == "KIND_QUARTER" DESC;
	`);

	const civilizations = dbCache.query(`
		SELECT DISTINCT 
			c.CivilizationType, 
			c.CivilizationName, 
			a.AgeType, 
			a.Name AS AgeName, 
			a.ChronologyIndex 
		FROM Civilizations c 
		INNER JOIN Ages a ON c.Domain = a.PlayerCivilizationDomain 
		ORDER BY a.ChronologyIndex ASC;
	`);

	const itemsByType = new Map<string, Database.DbRow[]>();
	for (const item of civilizationItems) {
		const civType = item.CivilizationType as string;
		if (!itemsByType.has(civType)) {
			itemsByType.set(civType, []);
		}
		itemsByType.get(civType)!.push(item);
	}

	for (const row of civilizations) {
		const civType = row.CivilizationType as string;
		const data: CivilizationSyncretismUnlocks = {
			CivilizationName: row.CivilizationName as string,
			CivilizationType: civType,
			AgeType: row.AgeType as string,
			AgeName: row.AgeName as string,
			Infrastructure: [],
			Unit: [],
		};

		const unlocks = itemsByType.get(civType) ?? [];
		for (const unlock of unlocks) {
			const unlockData: SyncretismUnlockOption = {
				Type: unlock.Type as string,
				Kind: unlock.Kind as string,
				Name: unlock.Name as string,
				Description: unlock.Description as string,
			};

			const isUnit = String(unlock.Unit).toLowerCase() === "true" || unlock.Unit === 1;
			const isInfra = String(unlock.Infrastructure).toLowerCase() === "true" || unlock.Infrastructure === 1;

			if (isUnit) data.Unit.push(unlockData);
			if (isInfra) data.Infrastructure.push(unlockData);
		}

		info.set(row.CivilizationType as string, data);
	}

	return { Info: info };
}

export const SyncretismDataModel = createSyncretismDataModel();
